"""Filtering of Ghidra auto-generated function names (P1 roadmap improvement).

Ghidra assigns synthetic, address-based names to blocks without a symbol:
exception handlers (``Unwind@1000a570``, ``Catch@10018f9e``), unnamed functions
(``FUN_1800a2b0``), labels, thunks... When the binary is rebuilt and addresses
shift, those names "change" even though the code is the same, and the name diff
counts them as added/removed functions.

In the real P1 bundle (full run, 2026-04) 80% of the names in the diff (260 of
324) were of this kind. Filtering them leaves only changes with a real name.
"""

from __future__ import annotations

import re

# [thunk_][EXT_] + synthetic prefix + separator + hex address (>= 4 digits).
# Covers FUN_..., thunk_FUN_..., thunk_EXT_FUN_... (thunks to externals without a symbol),
# Unwind@..., Catch@..., LAB_..., DAT_..., switchD_... and caseD_...
_AUTO_NAME_RE = re.compile(
    r"^(?:thunk_)?(?:EXT_)?(?:Unwind|Catch|Catch_All|FUN|SUB|LAB|DAT|switchD|caseD)[@_][0-9a-fA-F]{4,}$"
)


def is_autogenerated(name: str) -> bool:
    """True if the name is a synthetic, address-based Ghidra name."""
    return bool(_AUTO_NAME_RE.match(name or ""))


def filter_names(names: list[str]) -> tuple[list[str], int]:
    """Return (real names, number of auto-generated names discarded)."""
    real = [n for n in names or [] if not is_autogenerated(n)]
    return real, len(names or []) - len(real)


def is_runtime_helper(name: str) -> bool:
    """C runtime / compiler helper (``__alloca_probe``, ``_lock``,
    ``__dllonexit``...). If the "new" functions are mostly of this kind, the
    change points to a relink with another CRT/toolchain, not to new logic."""
    return (name or "").startswith("_")


def is_delay_load(name: str) -> bool:
    """Delay-load import thunk (``DelayLoad_WinHttpOpen``): indicates a
    dependency added to or removed from the binary, not one of its own functions."""
    return (name or "").startswith("DelayLoad_")
